```ts
import { describe, it, expect, beforeEach } from 'vitest';
import { WatchlistStore } from '../app/watchlist-store';
import { TmdbMovie } from '../app/movie';

function tmdb(id: number, title: string): TmdbMovie {
  return { id, title, release_date: '2024-01-01', poster_path: null, overview: 'An overview.' };
}

describe('WatchlistStore clearWatched', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('removes only the watched items and keeps remaining order', () => {
    const store = new WatchlistStore();
    store.add(tmdb(1, 'Watched One'));
    store.add(tmdb(2, 'Unwatched One'));
    store.add(tmdb(3, 'Watched Two'));
    store.add(tmdb(4, 'Unwatched Two'));
    store.toggleWatched(1);
    store.toggleWatched(3);

    store.clearWatched();

    const remaining = store.items();
    expect(remaining.map((item) => item.id)).toEqual([2, 4]);
    expect(remaining.every((item) => !item.watched)).toBe(true);
    expect(store.count()).toBe(2);
    expect(store.watchedCount()).toBe(0);
  });

  it('does nothing when no movie is watched', () => {
    const store = new WatchlistStore();
    store.add(tmdb(2, 'Unwatched One'));
    store.add(tmdb(4, 'Unwatched Two'));

    store.clearWatched();

    expect(store.items().map((item) => item.id)).toEqual([2, 4]);
    expect(store.count()).toBe(2);
  });

  it('can empty the list when every movie is watched', () => {
    const store = new WatchlistStore();
    store.add(tmdb(1, 'Watched One'));
    store.toggleWatched(1);

    store.clearWatched();

    expect(store.items()).toEqual([]);
    expect(store.count()).toBe(0);
    expect(store.watchedCount()).toBe(0);
  });

  it('persists the cleared list for the next session', () => {
    const store = new WatchlistStore();
    store.add(tmdb(1, 'Watched One'));
    store.add(tmdb(2, 'Unwatched One'));
    store.toggleWatched(1);
    store.clearWatched();

    const reloaded = new WatchlistStore();
    expect(reloaded.items().map((item) => item.id)).toEqual([2]);
    expect(reloaded.count()).toBe(1);
  });
});
```

